fn validate_sync(value: &SyncRecord, position: u64) -> Result<()> {
  if value.column > 0x00ff {
    return Err(Error::invalid(
      position,
      "Sync column exceeds the BIFF8 column range",
    ));
  }
  Ok(())
}

