    let reserved3 = reader.read_u16()?;
    let property_count = usize::from(reader.read_u16()?);
    let mut properties = Vec::with_capacity(property_count);
    for _ in 0..property_count {
      properties.push(ExtProperty::read(reader)?);
    }
