  #[test]
  fn workbook_calculation_future_records_enforce_normative_boolean_fields() {
    let header = |record_type| FrtHeader {
      record_type,
      flags: FrtFlags::empty(),
      reserved: 0,
    };
    let recalc = RecalcIdRecord {
      record_type: 449,
      reserved: 0,
      engine_build: 125_725,
    };
    let bytes = encode_sdk(&recalc).unwrap();
    assert_eq!(bytes.len(), 8);
    assert_eq!(
      parse_sdk::<RecalcIdRecord>(&bytes, 0, RECALC_ID).unwrap(),
      recalc
    );

    let multithreaded = MtrSettingsRecord {
      header: header(MTR_SETTINGS),
      enabled: 1,
      user_set_thread_count: 1,
      thread_count: 8,
    };
    let bytes = encode_sdk(&multithreaded).unwrap();
    assert_eq!(
      parse_sdk::<MtrSettingsRecord>(&bytes, 0, MTR_SETTINGS).unwrap(),
      multithreaded
    );

    let forced = ForceFullCalculationRecord {
      header: header(FORCE_FULL_CALCULATION),
      ignore_dependencies: 1,
    };
    assert_eq!(
      parse_sdk::<ForceFullCalculationRecord>(
        &encode_sdk(&forced).unwrap(),
        0,
        FORCE_FULL_CALCULATION,
      )
      .unwrap(),
      forced
    );
    let compressed = CompressPicturesRecord {
      header: header(COMPRESS_PICTURES),
      auto_compress_pictures: 0,
    };
    assert_eq!(
      parse_sdk::<CompressPicturesRecord>(&encode_sdk(&compressed).unwrap(), 0, COMPRESS_PICTURES,)
        .unwrap(),
      compressed
    );
    let compatibility = Compat12Record {
      header: header(COMPAT12),
      no_compatibility_check: 1,
    };
    assert_eq!(
      parse_sdk::<Compat12Record>(&encode_sdk(&compatibility).unwrap(), 0, COMPAT12).unwrap(),
      compatibility
    );

    assert!(
      encode_sdk(&RecalcIdRecord {
        reserved: 1,
        ..recalc
      })
      .is_err()
    );
    assert!(
      encode_sdk(&MtrSettingsRecord {
        thread_count: 0,
        ..multithreaded
      })
      .is_err()
    );
    assert!(
      encode_sdk(&ForceFullCalculationRecord {
        ignore_dependencies: 2,
        ..forced
      })
      .is_err()
    );
    assert!(
      encode_sdk(&CompressPicturesRecord {
        auto_compress_pictures: 2,
        ..compressed
      })
      .is_err()
    );
    assert!(
      encode_sdk(&Compat12Record {
        no_compatibility_check: 2,
        ..compatibility
      })
      .is_err()
    );
  }

  #[test]
  fn biff_relayout_updates_sheet_and_index_file_pointers_after_growth() {
    let mut stream = BiffStream {
      records: vec![
        BiffRecord {
          offset: 0,
          data: BiffRecordData::Bof(BofRecord {
            version: 0x0600,
            document_type: 0x0005,
            build_identifier: 0,
            build_year: 0x07cc,
            history_flags: 1,
            lowest_version: 6,
          }),
        },
        BiffRecord {
          offset: 20,
          data: BiffRecordData::BoundSheet8(BoundSheet8Record {
            sheet_bof_offset: 37,
            state: 0,
            sheet_type: 0,
            name: ShortXlUnicodeString {
              flags: 0,
              value: "S".to_owned(),
            },
          }),
        },
        BiffRecord {
          offset: 33,
          data: BiffRecordData::Eof,
        },
        BiffRecord {
          offset: 37,
          data: BiffRecordData::Bof(BofRecord {
            version: 0x0600,
            document_type: 0x0010,
            build_identifier: 0,
            build_year: 0x07cc,
            history_flags: 1,
            lowest_version: 6,
          }),
        },
        BiffRecord {
          offset: 57,
          data: BiffRecordData::Index(IndexRecord {
            reserved1: 0,
            first_row: 0,
            last_row_exclusive: 0,
            def_col_width_offset: 77,
            dbcell_offsets: Vec::new(),
          }),
        },
        BiffRecord {
          offset: 77,
          data: BiffRecordData::FixedU16 {
            kind: FixedU16RecordKind::DefaultColWidth,
            value: 8,
          },
        },
        BiffRecord {
          offset: 83,
          data: BiffRecordData::Eof,
        },
      ],
      trailing_padding: Vec::new(),
    };
    let BiffRecordData::BoundSheet8(sheet) = &mut stream.records[1].data else {
      unreachable!()
    };
    sheet.name.value = "Sheet1".to_owned();

    let mut invalid = stream.clone();
    let BiffRecordData::BoundSheet8(sheet) = &mut invalid.records[1].data else {
      unreachable!()
    };
    sheet.sheet_bof_offset = 999;
    let unchanged_after_failure = invalid.clone();
    assert!(invalid.relayout().is_err());
    assert_eq!(invalid, unchanged_after_failure);

    let bytes = stream.to_bytes().unwrap();
    let parsed = BiffStream::from_bytes(&bytes).unwrap();
    assert_eq!(parsed.records[3].offset, 42);
    assert!(matches!(
      &parsed.records[1].data,
      BiffRecordData::BoundSheet8(BoundSheet8Record {
        sheet_bof_offset: 42,
        ..
      })
    ));
    assert!(matches!(
      &parsed.records[4].data,
      BiffRecordData::Index(IndexRecord {
        def_col_width_offset: 82,
        ..
      })
    ));
    assert_eq!(parsed.records[5].offset, 82);
  }

  #[test]
  fn biff_relayout_updates_dbcell_relative_offsets_after_insertion() {
    let mut stream = BiffStream {
      records: vec![
        BiffRecord {
          offset: 0,
          data: BiffRecordData::Unknown {
            record_type: ROW,
            payload: vec![0; 16],
          },
        },
        BiffRecord {
          offset: 999,
          data: BiffRecordData::Unknown {
            record_type: 0x1234,
            payload: vec![0; 2],
          },
        },
        BiffRecord {
          offset: 20,
          data: BiffRecordData::Unknown {
            record_type: NUMBER,
            payload: vec![0; 14],
          },
        },
        BiffRecord {
          offset: 38,
          data: BiffRecordData::DbCell(DbCellRecord {
            row_offset: 38,
            cell_offsets: vec![0],
          }),
        },
      ],
      trailing_padding: Vec::new(),
    };

    stream.relayout().unwrap();
    assert_eq!(
      stream
        .records
        .iter()
        .map(|record| record.offset)
        .collect::<Vec<_>>(),
      [0, 20, 26, 44]
    );
    assert!(matches!(
        &stream.records[3].data,
        BiffRecordData::DbCell(DbCellRecord {
            row_offset: 44,
            cell_offsets,
        }) if cell_offsets == &[6]
    ));
  }

  #[test]
  fn biff_write_plan_borrows_unchanged_payloads_during_relayout() {
    let payload = vec![0x5a; MAX_BIFF_RECORD_DATA];
    let stream = BiffStream {
      records: vec![
        BiffRecord {
          offset: 0,
          data: BiffRecordData::Unknown {
            record_type: 0x1234,
            payload,
          },
        },
        BiffRecord {
          offset: 999_999,
          data: BiffRecordData::Eof,
        },
      ],
      trailing_padding: Vec::new(),
    };

    let plan = BiffWritePlan::new(&stream, false).unwrap();
    assert!(matches!(&plan.records[0].data, Cow::Borrowed(_)));
    assert!(matches!(&plan.records[1].data, Cow::Borrowed(_)));
    assert_eq!(
      plan.records[1].new_offset,
      (MAX_BIFF_RECORD_DATA + 4) as u32
    );

    let bytes = stream.to_bytes().unwrap();
    let reopened = BiffStream::from_bytes(&bytes).unwrap();
    assert_eq!(
      reopened.records[1].offset,
      (MAX_BIFF_RECORD_DATA + 4) as u32
    );
    assert_eq!(stream.records[1].offset, 999_999);
  }

