  #[test]
  fn active_x_picture_formula_is_fully_typed_and_exact() {
    // FtPictFmla from an Excel ActiveX CommandButton. cbClass counts the 21
    // characters, while the XLUnicodeStringNoCch also carries its flag byte.
    let bytes = [
      0x24, 0x00, 0x05, 0x00, 0x40, 0x42, 0x3e, 0x03, 0x02, 0x80, 0xcd, 0xb4, 0x04, 0x03, 0x15,
      0x00, 0x00, b'F', b'o', b'r', b'm', b's', b'.', b'C', b'o', b'm', b'm', b'a', b'n', b'd',
      b'B', b'u', b't', b't', b'o', b'n', b'.', b'1', 0x00, 0x00, 0x00, 0x00, 0x54, 0x00, 0x00,
      0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    ];
    let flags = ObjPictureFlags::CONTROL | ObjPictureFlags::CONTROL_STREAM;
    let value = ObjSubrecordData::parse(
      0x0009,
      bytes.len() as u16,
      &bytes,
      Some(0x0008),
      Some(flags),
      Limits::default(),
    )
    .unwrap();
    let ObjSubrecordData::PictureFormula(picture) = &value else {
      panic!("expected typed FtPictFmla");
    };
    let ObjFormulaData::Parsed {
      embed_info: Some(embed),
      padding,
      ..
    } = &picture.formula.data
    else {
      panic!("expected typed PictFmlaEmbedInfo");
    };
    assert_eq!(embed.declared_class_count, 21);
    assert_eq!(embed.class_name.as_ref().unwrap().character_count(), 21);
    assert!(padding.is_empty());
    assert_eq!(picture.control_stream_position, Some(0));
    assert_eq!(picture.control_stream_size, Some(84));
    let key = picture.key.as_ref().unwrap();
    assert!(key.key.is_empty());
    assert!(matches!(key.linked_cell.data, ObjFormulaData::Empty));
    assert!(matches!(key.list_fill_range.data, ObjFormulaData::Empty));
    assert!(picture.compatibility_trailing.is_empty());
    assert_eq!(value.to_bytes(Some(flags)).unwrap(), bytes);
  }

  #[test]
  fn self_relative_security_descriptor_is_fully_typed_and_exact() {
    let bytes = [
      0x01, 0x00, 0x04, 0x80, 0x40, 0x00, 0x00, 0x00, 0x4c, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
      0x00, 0x14, 0x00, 0x00, 0x00, 0x02, 0x00, 0x2c, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x00,
      0x24, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01, 0x05, 0x00, 0x00, 0x00, 0x00, 0x00, 0x05, 0x15,
      0x00, 0x00, 0x00, 0x99, 0xb8, 0xcb, 0x8a, 0x98, 0x00, 0xc0, 0x1a, 0xfe, 0x9a, 0x22, 0x80,
      0xeb, 0x03, 0x00, 0x00, 0x01, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00,
      0x00, 0x01, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00,
    ];
    let descriptor = SecurityDescriptor::from_bytes(&bytes).unwrap();
    assert!(
      descriptor
        .control
        .contains(SecurityDescriptorControl::SELF_RELATIVE)
    );
    let dacl = descriptor.dacl.as_ref().unwrap();
    assert_eq!(dacl.value.entries.len(), 1);
    assert_eq!(dacl.value.entries[0].ace_type, BasicAceType::AccessDenied);
    assert_eq!(dacl.value.entries[0].trustee.sub_authorities.len(), 5);
    assert_eq!(descriptor.owner.as_ref().unwrap().offset, 0x40);
    assert_eq!(descriptor.group.as_ref().unwrap().offset, 0x4c);
    assert!(descriptor.padding.is_empty());
    assert_eq!(descriptor.to_bytes(bytes.len()).unwrap(), bytes);
  }

